//! 📏️ The complete original page bound is paid once and the next native binding refuses before allocation.
use semio_framework_job::*;
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(1000)}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn retained_payload_max_plus_one_zero_grant_nested_and_exact_close_are_owned(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let extent=law["pageBytes"].as_u64().unwrap()as usize;let pages=law["pageCount"].as_u64().unwrap()as usize;assert_eq!((extent,pages),(JOB_PAYLOAD_PAGE_BYTES,JOB_PAYLOAD_OPERATION_PAGES));let count=law["sourceBytes"].as_u64().unwrap()as usize;let mut source=vec![0u8;count];for(index,byte)in source.iter_mut().enumerate(){*byte=(index/extent)as u8;}let pointer=source.as_ptr();let stock_bytes=law["stockBytes"].as_u64().unwrap()as usize;let stock=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:stock_bytes,maximum_capacity_bytes:stock_bytes,maximum_release_bytes:stock_bytes,maximum_depth:64};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:extent,maximum_release_bytes:stock_bytes,maximum_depth:64};let(mut caller,root)=observe(||OriginalJobFixtureCaller::admit(OperationId(90001),Generation(7),stock,clock,1000000,100000));let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::CheckpointState);let mut cursor=0;let mut born=root.0;let mut released=root.1;
 for turn in 0..4096{if cursor==count-1{break}let(answer,heap)=observe(||caller.turn(grant,|cx|{if !builder.is_initialized(){builder.advance_initialization(cx)?;}else{builder.append_original(cx,&source[..count-1],&mut cursor)?;}cx.consume_fuel(1);Ok(())}));answer.unwrap();assert_eq!(heap,(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));born+=heap.0;released+=heap.1;assert_eq!(source.as_ptr(),pointer);assert!(turn<4095);}
 let original=builder.original().unwrap();assert_eq!(original.page_count(),pages);assert_eq!(original.allocated_capacity_bytes(),extent*pages);for index in 0..pages{assert_eq!(original.page(index).unwrap(),&source[index*extent..(index+1)*extent]);}let last=original.page(pages-1).unwrap().as_ptr();let(answer,heap)=observe(||caller.turn(grant,|cx|Ok(builder.append_original(cx,&source,&mut cursor)?)));assert!(answer.is_err());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert_eq!(cursor,count-1);assert_eq!(builder.original().unwrap().page(pages-1).unwrap().as_ptr(),last);
 let close=RetainedCloneGrant{maximum_release_bytes:extent,..grant};let denied=RetainedCloneGrant{maximum_items:0,..close};let(answer,heap)=observe(||caller.turn(denied,|cx|Ok(builder.close_step(cx)?)));assert!(!answer.unwrap());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());let mut physical_turns=0;
 for turn in 0..pages+4{if builder.terminal_is_empty(){break}let(answer,heap)=observe(||caller.turn(close,|cx|{let done=builder.close_step(cx)?;cx.consume_fuel(1);Ok(done)}));answer.unwrap();let receipt=caller.receipt();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));if heap.1>0{assert_eq!(heap.1,extent);physical_turns+=1;}born+=heap.0;released+=heap.1;assert!(turn<pages+3);}assert!(builder.terminal_is_empty());assert_eq!(physical_turns,pages);assert_eq!(observe(||drop(builder)).1,(0,0));let(root_release,heap)=observe(||caller.retire(close));assert_eq!(heap,(0,root_release));released+=root_release;assert_eq!(born,released);assert_eq!(source.as_ptr(),pointer);eprintln!("[DEBUG] actual Original maximum={pages} nativeExtent={extent} plusOneHeap0 sameSource zeroItemsClose0 exactPageCloses={physical_turns} paidBornRelease={born} terminalDrop0");
}
